/**
 * Orvix Response Alternatives Service
 * Handles data structures, relationships, normalization, and switching
 * for multiple assistant response alternatives associated with a single user message.
 *
 * Architecture:
 * - A single user message (identified by stable `id`, e.g., 'user-1718000000000') can have
 *   multiple associated assistant response alternatives generated by different AI providers/models.
 * - Each alternative is an independently identifiable record with its own content, provider,
 *   modelUsed, responseTimeMs, timestamp, and metadata.
 * - The assistant message contains an `alternatives` collection and points to `activeAlternativeId`.
 * - The active alternative is projected onto root message properties (`content`, `provider`, `modelUsed`,
 *   `responseTimeMs`) to preserve seamless backward compatibility with all existing rendering,
 *   streaming, clipboard copying, voice read-aloud, and export systems.
 */

/**
 * Generates a stable, unique identifier for a response alternative.
 * @param {string} [provider='assistant']
 * @returns {string}
 */
export function generateAlternativeId(provider = 'assistant') {
  const cleanProvider = (provider || 'assistant').toLowerCase().replace(/[^a-z0-9_-]/g, '');
  const timestamp = Date.now();
  const randomPart = Math.random().toString(36).substring(2, 8);
  return `alt-${cleanProvider}-${timestamp}-${randomPart}`;
}

/**
 * Creates a well-formed Response Alternative record.
 *
 * @param {Object} params
 * @param {string} [params.id]
 * @param {string|null} [params.parentMessageId=null] - The user message ID that prompted this alternative
 * @param {string} [params.content='']
 * @param {string} [params.provider='gemini']
 * @param {string|null} [params.modelUsed=null]
 * @param {number|null} [params.responseTimeMs=null]
 * @param {string} [params.timestamp='']
 * @param {number} [params.createdAt=Date.now()]
 * @param {Array} [params.referencedAttachments=[]]
 * @param {boolean} [params.isError=false]
 * @param {boolean} [params.isStopped=false]
 * @returns {Object} Clean ResponseAlternative object
 */
export { sanitizeModelForProvider } from './providerModelSanitizer.js';
import { sanitizeStoredDisplayModel } from './providerModelSanitizer.js';

export function createAlternativeRecord({
  id = null,
  parentMessageId = null,
  interactionId = null,
  content = '',
  provider = 'gemini',
  modelUsed = null,
  responseTimeMs = null,
  timestamp = '',
  createdAt = null,
  createdAtMs = null,
  referencedAttachments = [],
  isError = false,
  isStopped = false
} = {}) {
  const chosenProvider = provider || 'gemini';
  const cleanModel = sanitizeStoredDisplayModel(chosenProvider, modelUsed);
  const resolvedCreated = typeof createdAt === 'number' && !isNaN(createdAt) ? createdAt : Date.now();
  return {
    id: id || generateAlternativeId(chosenProvider),
    parentMessageId: parentMessageId || null,
    interactionId: interactionId || null,
    sender: 'assistant',
    content: typeof content === 'string' ? content : '',
    provider: chosenProvider,
    modelUsed: cleanModel || null,
    responseTimeMs: typeof responseTimeMs === 'number' && !isNaN(responseTimeMs) ? responseTimeMs : null,
    timestamp: timestamp || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    createdAt: resolvedCreated,
    createdAtMs: typeof createdAtMs === 'number' && !isNaN(createdAtMs) ? createdAtMs : resolvedCreated,
    referencedAttachments: Array.isArray(referencedAttachments) ? [...referencedAttachments] : [],
    isError: Boolean(isError),
    isStopped: Boolean(isStopped)
  };
}

/**
 * Normalizes an assistant message to ensure it contains a valid alternatives list,
 * an activeAlternativeId, and a linked parentMessageId.
 * Gracefully handles legacy messages that do not have alternative-response metadata.
 *
 * @param {Object} message - The assistant message to normalize
 * @param {Object|null} [precedingUserMessage=null] - Preceding user message for parent linking
 * @returns {Object} Normalized message with alternatives structure
 */
function hasActiveAlternativeRecord(alternatives, activeAlternativeId) {
  if (!activeAlternativeId || !Array.isArray(alternatives) || alternatives.length === 0) {
    return false;
  }
  for (let i = 0; i < alternatives.length; i++) {
    const alt = alternatives[i];
    if (alt && alt.id === activeAlternativeId) {
      return true;
    }
  }
  return false;
}

export function normalizeAssistantMessage(message, precedingUserMessage = null) {
  if (!message || message.sender === 'user') {
    return message;
  }

  const baseMessage = message.sender === 'assistant' ? message : { ...message, sender: 'assistant' };

  const parentMessageId =
    baseMessage.parentMessageId ||
    (precedingUserMessage?.id ? precedingUserMessage.id : null);

  const interactionId =
    baseMessage.interactionId ||
    (precedingUserMessage?.interactionId ? precedingUserMessage.interactionId : null);

  // Fast check: if already fully normalized with alternatives, valid activeAlternativeId,
  // and matching parentMessageId and interactionId, avoid recreating objects
  if (
    message.sender === 'assistant' &&
    Array.isArray(message.alternatives) &&
    message.alternatives.length > 0 &&
    message.activeAlternativeId &&
    (!parentMessageId || message.parentMessageId === parentMessageId) &&
    (!interactionId || message.interactionId === interactionId) &&
    hasActiveAlternativeRecord(message.alternatives, message.activeAlternativeId)
  ) {
    return message;
  }

  const createdAt =
    typeof baseMessage.createdAt === 'number' && !isNaN(baseMessage.createdAt)
      ? baseMessage.createdAt
      : Date.now();

  const createdAtMs =
    typeof baseMessage.createdAtMs === 'number' && !isNaN(baseMessage.createdAtMs)
      ? baseMessage.createdAtMs
      : createdAt;

  let alternatives = [];

  if (Array.isArray(baseMessage.alternatives) && baseMessage.alternatives.length > 0) {
    // Message already has alternatives array; ensure each alternative is well-formed
    alternatives = message.alternatives.map((alt) =>
      createAlternativeRecord({
        id: alt.id,
        parentMessageId: alt.parentMessageId || parentMessageId,
        interactionId: alt.interactionId || interactionId,
        content: alt.content,
        provider: alt.provider || message.provider || 'gemini',
        modelUsed: alt.modelUsed || message.modelUsed || null,
        responseTimeMs: alt.responseTimeMs,
        timestamp: alt.timestamp || message.timestamp,
        createdAt: alt.createdAt || createdAt,
        createdAtMs: alt.createdAtMs || createdAtMs,
        referencedAttachments: alt.referencedAttachments || message.referencedAttachments || [],
        isError: alt.isError,
        isStopped: alt.isStopped
      })
    );
  } else {
    // Legacy message without alternatives: wrap existing message content as Alternative #1
    const initialAltId = message.id ? `alt-${message.id}` : generateAlternativeId(message.provider || 'gemini');
    alternatives = [
      createAlternativeRecord({
        id: initialAltId,
        parentMessageId,
        interactionId,
        content: message.content || '',
        provider: message.provider || 'gemini',
        modelUsed: message.modelUsed || null,
        responseTimeMs: message.responseTimeMs,
        timestamp: message.timestamp || '',
        createdAt,
        createdAtMs,
        referencedAttachments: message.referencedAttachments || [],
        isError: message.isError,
        isStopped: message.isStopped
      })
    ];
  }

  // Ensure activeAlternativeId points to an existing alternative in the list
  let activeAlternativeId = message.activeAlternativeId;
  let activeAlt = alternatives.find((a) => a.id === activeAlternativeId);

  if (!activeAlt) {
    activeAlt = alternatives[0];
    activeAlternativeId = activeAlt.id;
  }

  // Project active alternative's attributes onto the root message object
  return {
    ...message,
    parentMessageId,
    interactionId,
    createdAt,
    createdAtMs,
    activeAlternativeId,
    alternatives,
    content: activeAlt.content,
    provider: activeAlt.provider,
    modelUsed: activeAlt.modelUsed,
    responseTimeMs: activeAlt.responseTimeMs,
    timestamp: activeAlt.timestamp || message.timestamp,
    referencedAttachments:
      activeAlt.referencedAttachments && activeAlt.referencedAttachments.length > 0
        ? activeAlt.referencedAttachments
        : message.referencedAttachments
  };
}

/**
 * Adds a new alternative response to an assistant message and makes it active.
 * The original response and any previously generated alternatives remain completely unchanged.
 *
 * @param {Object} assistantMessage - Existing assistant message
 * @param {Object} newAlternativeData - Data for the new alternative
 * @returns {Object} Updated assistant message containing all alternatives
 */
export function addAlternativeToAssistantMessage(assistantMessage, newAlternativeData = {}) {
  const normalized = normalizeAssistantMessage(assistantMessage);
  const parentMessageId = normalized.parentMessageId || newAlternativeData.parentMessageId || null;

  const newAlternative = createAlternativeRecord({
    ...newAlternativeData,
    parentMessageId
  });

  const updatedAlternatives = [...normalized.alternatives, newAlternative];

  return {
    ...normalized,
    activeAlternativeId: newAlternative.id,
    alternatives: updatedAlternatives,
    content: newAlternative.content,
    provider: newAlternative.provider,
    modelUsed: newAlternative.modelUsed,
    responseTimeMs: newAlternative.responseTimeMs,
    timestamp: newAlternative.timestamp,
    referencedAttachments:
      newAlternative.referencedAttachments && newAlternative.referencedAttachments.length > 0
        ? newAlternative.referencedAttachments
        : normalized.referencedAttachments
  };
}

/**
 * Switches the active alternative of an assistant message to targetAlternativeId.
 * Updates projected properties (content, provider, model, responseTimeMs) accordingly.
 *
 * @param {Object} assistantMessage - Target assistant message
 * @param {string} targetAlternativeId - ID of alternative to make active
 * @returns {Object} Updated assistant message with newly active alternative projected
 */
export function switchActiveAlternativeInMessage(assistantMessage, targetAlternativeId) {
  if (!assistantMessage || !Array.isArray(assistantMessage.alternatives)) {
    return assistantMessage;
  }

  const targetAlt = assistantMessage.alternatives.find((a) => a.id === targetAlternativeId);
  if (!targetAlt) {
    return assistantMessage;
  }

  return {
    ...assistantMessage,
    activeAlternativeId: targetAlternativeId,
    content: targetAlt.content,
    provider: targetAlt.provider,
    modelUsed: targetAlt.modelUsed,
    responseTimeMs: targetAlt.responseTimeMs,
    timestamp: targetAlt.timestamp || assistantMessage.timestamp,
    referencedAttachments:
      targetAlt.referencedAttachments && targetAlt.referencedAttachments.length > 0
        ? targetAlt.referencedAttachments
        : assistantMessage.referencedAttachments
  };
}

/**
 * Updates properties of the active alternative inside an assistant message.
 * Also synchronizes root projected properties.
 *
 * @param {Object} assistantMessage
 * @param {Object} updates
 * @returns {Object} Updated assistant message
 */
export function updateActiveAlternativeInMessage(assistantMessage, updates = {}) {
  if (!assistantMessage) return assistantMessage;

  const normalized = normalizeAssistantMessage(assistantMessage);
  if (!normalized || !Array.isArray(normalized.alternatives) || normalized.alternatives.length === 0) {
    return {
      ...(normalized || assistantMessage),
      ...updates,
      sender: 'assistant',
      content: typeof updates.content === 'string' ? updates.content : (normalized?.content || assistantMessage?.content || '')
    };
  }

  const activeId = normalized.activeAlternativeId;

  const updatedAlternatives = normalized.alternatives.map((alt) => {
    if (alt.id !== activeId) return alt;
    return {
      ...alt,
      ...updates,
      id: alt.id // Never mutate alternative ID
    };
  });

  const activeAlt = updatedAlternatives.find((a) => a.id === activeId) || updatedAlternatives[0];

  return {
    ...normalized,
    ...updates,
    activeAlternativeId: activeId,
    alternatives: updatedAlternatives,
    content: typeof updates.content === 'string' ? updates.content : activeAlt.content,
    provider: updates.provider || activeAlt.provider,
    modelUsed: updates.modelUsed !== undefined ? updates.modelUsed : activeAlt.modelUsed,
    responseTimeMs:
      updates.responseTimeMs !== undefined ? updates.responseTimeMs : activeAlt.responseTimeMs
  };
}

/**
 * Resolves the currently active alternative record from an assistant message.
 * @param {Object} assistantMessage
 * @returns {Object|null}
 */
export function getActiveAlternative(assistantMessage) {
  if (!assistantMessage) return null;
  const normalized = normalizeAssistantMessage(assistantMessage);
  const alts = Array.isArray(normalized.alternatives) ? normalized.alternatives : [];
  if (alts.length === 0) return null;
  const activeId = normalized.activeAlternativeId;
  return alts.find((a) => a.id === activeId) || alts[0] || null;
}

/**
 * Updates a specific alternative by ID inside an assistant message.
 * If the updated alternative is currently active, root projected properties are synchronized.
 *
 * @param {Object} assistantMessage
 * @param {string} targetId - Alternative ID to update
 * @param {Object} updates
 * @returns {Object} Updated assistant message
 */
export function updateAlternativeByIdInMessage(assistantMessage, targetId, updates = {}) {
  if (!assistantMessage) return assistantMessage;

  const normalized = normalizeAssistantMessage(assistantMessage);
  const targetAlternativeId = targetId || normalized.activeAlternativeId;

  const updatedAlternatives = normalized.alternatives.map((alt) => {
    if (alt.id !== targetAlternativeId) return alt;
    return {
      ...alt,
      ...updates,
      id: alt.id // Never mutate alternative ID
    };
  });

  const activeId = normalized.activeAlternativeId;
  const activeAlt = updatedAlternatives.find((a) => a.id === activeId) || updatedAlternatives[0];

  const rootSync = targetAlternativeId === activeId ? updates : {};

  return {
    ...normalized,
    ...rootSync,
    activeAlternativeId: activeId,
    alternatives: updatedAlternatives,
    content: activeAlt.content,
    provider: activeAlt.provider,
    modelUsed: activeAlt.modelUsed,
    responseTimeMs: activeAlt.responseTimeMs
  };
}

/**
 * Normalizes all messages in a conversation so all assistant messages
 * have parentMessageId and valid alternatives array.
 *
 * @param {Array} messages - Full conversation messages array
 * @returns {Array} Normalized messages array
 */
export function ensureConversationAlternatives(messages = []) {
  if (!Array.isArray(messages)) return [];
  const len = messages.length;
  if (len === 0) return messages;

  let userById = null;
  let userByInteractionId = null;
  let lastUserMessage = null;
  let next = null;

  const ensureUserLookups = () => {
    if (userById !== null) return;
    userById = new Map();
    userByInteractionId = new Map();
    for (let j = 0; j < len; j++) {
      const m = messages[j];
      if (m?.sender === 'user' && m.id) {
        userById.set(m.id, m);
      }
    }
    for (const u of userById.values()) {
      if (u.interactionId && !userByInteractionId.has(u.interactionId)) {
        userByInteractionId.set(u.interactionId, u);
      }
    }
  };

  for (let i = 0; i < len; i++) {
    const msg = messages[i];
    if (!msg) continue;

    if (msg.sender === 'user') {
      lastUserMessage = msg;
      continue;
    }

    if (msg.sender === 'assistant') {
      // Zero-allocation fast path when assistant message already carries parentMessageId,
      // interactionId, and a valid active alternative record.
      if (
        msg.parentMessageId &&
        msg.interactionId &&
        Array.isArray(msg.alternatives) &&
        msg.alternatives.length > 0 &&
        hasActiveAlternativeRecord(msg.alternatives, msg.activeAlternativeId)
      ) {
        continue;
      }

      ensureUserLookups();
      const linkedUser =
        (msg.parentMessageId && userById.get(msg.parentMessageId)) ||
        (msg.interactionId && userByInteractionId.get(msg.interactionId)) ||
        lastUserMessage;
      const normalized = normalizeAssistantMessage(msg, linkedUser);
      if (normalized !== msg) {
        if (next === null) {
          next = messages.slice();
        }
        next[i] = normalized;
      }
    }
  }

  return next !== null ? next : messages;
}

function isFastNormalizedAssistantForUser(msg, parentUser) {
  if (!msg || !parentUser || !parentUser.id) return false;
  if (msg.parentMessageId !== parentUser.id) return false;
  if (!msg.interactionId && parentUser.interactionId) return false;
  return hasActiveAlternativeRecord(msg.alternatives, msg.activeAlternativeId);
}

function canReuseMessageSlotOrder(prevMsg, nextMsg) {
  if (!prevMsg || !nextMsg) return false;
  if (!nextMsg.id || prevMsg.id !== nextMsg.id) return false;
  if (prevMsg.sender !== nextMsg.sender) return false;
  if (prevMsg.parentMessageId !== nextMsg.parentMessageId) return false;
  if (prevMsg.interactionId !== nextMsg.interactionId) return false;
  if (prevMsg.createdAtMs !== nextMsg.createdAtMs) return false;
  if (prevMsg.createdAt !== nextMsg.createdAt) return false;

  if (nextMsg.sender === 'assistant') {
    if (
      !nextMsg.parentMessageId ||
      !Array.isArray(nextMsg.alternatives) ||
      nextMsg.alternatives.length === 0 ||
      !nextMsg.activeAlternativeId
    ) {
      return false;
    }
    const expectedParentId = nextMsg.parentMessageId;
    const expectedInteractionId = nextMsg.interactionId || null;
    const alts = nextMsg.alternatives;
    let foundActive = false;
    for (let i = 0; i < alts.length; i++) {
      const alt = alts[i];
      if (!alt || !alt.id) return false;
      if (alt.parentMessageId !== expectedParentId) {
        return false;
      }
      if (expectedInteractionId && alt.interactionId && alt.interactionId !== expectedInteractionId) {
        return false;
      }
      if (alt.id === nextMsg.activeAlternativeId) {
        foundActive = true;
      }
    }
    if (!foundActive) return false;
  }

  return true;
}

/**
 * Canonical Conversation Message Ordering & Association Engine
 *
 * Guarantees that:
 * 1. Every user message appears in its correct chronological order.
 * 2. Every AI response appears directly beneath its originating user message.
 * 3. Asynchronous completion order, retries, or model switching cannot corrupt or displace message order.
 * 4. Responses never become detached from their parent user request.
 * 5. Conversations restored from history/storage preserve exact parent-child pairing.
 *
 * @param {Array} messages - Unordered or partially ordered message array
 * @returns {Array} Canonically ordered and aligned message array
 */
export function orderConversationMessages(messages = []) {
  if (!Array.isArray(messages)) {
    return [];
  }
  const initialLen = messages.length;
  if (initialLen === 0) {
    return messages;
  }
  if (initialLen === 1) {
    return messages[0]?.sender === 'assistant'
      ? ensureConversationAlternatives(messages)
      : messages;
  }

  // Zero-allocation single-pass fast path:
  // If every user message is already chronological and every assistant message is already
  // normalized and positioned directly beneath its parent user message, return `messages` as-is.
  let canReturnInputDirectly = true;
  let fastParentUser = null;
  let fastLastUserTime = -Infinity;

  for (let i = 0; i < initialLen; i++) {
    const m = messages[i];
    if (!m) continue;
    if (m.sender === 'user') {
      const uTime = typeof m.createdAtMs === 'number' ? m.createdAtMs : (m.createdAt || null);
      if (uTime !== null && uTime < fastLastUserTime) {
        canReturnInputDirectly = false;
        break;
      }
      if (uTime !== null) {
        fastLastUserTime = uTime;
      }
      fastParentUser = m;
    } else if (m.sender === 'assistant') {
      if (!isFastNormalizedAssistantForUser(m, fastParentUser)) {
        canReturnInputDirectly = false;
        break;
      }
    }
  }

  if (canReturnInputDirectly) {
    return messages;
  }

  const normalized = ensureConversationAlternatives(messages);

  // Fast path after normalization: verify if the normalized list is already in strict canonical sequence
  let isAlreadyOrdered = true;
  let activeParentUser = null;
  let lastUserTime = -Infinity;

  for (let i = 0; i < normalized.length; i++) {
    const m = normalized[i];
    if (!m) continue;
    if (m.sender === 'user') {
      const uTime = typeof m.createdAtMs === 'number' ? m.createdAtMs : (m.createdAt || null);
      if (uTime !== null && uTime < lastUserTime) {
        isAlreadyOrdered = false;
        break;
      }
      if (uTime !== null) {
        lastUserTime = uTime;
      }
      activeParentUser = m;
    } else if (m.sender === 'assistant') {
      if (!activeParentUser) {
        isAlreadyOrdered = false;
        break;
      }
      const pId = m.parentMessageId;
      if (pId && pId !== activeParentUser.id) {
        isAlreadyOrdered = false;
        break;
      }
    }
  }

  if (isAlreadyOrdered) {
    return normalized;
  }

  // Canonical ordering pass:
  // Step 1: Catalog all user messages
  const userOrder = [];
  const userMap = new Map();
  const userIndexById = new Map();
  const assistantBuckets = new Map();
  const leadingOrphans = [];
  const trailingOrphans = [];

  for (let i = 0; i < normalized.length; i++) {
    const m = normalized[i];
    if (!m) continue;
    if (m.sender === 'user') {
      if (!userMap.has(m.id)) {
        userIndexById.set(m.id, userOrder.length);
        userOrder.push(m);
        userMap.set(m.id, m);
        assistantBuckets.set(m.id, []);
      } else {
        const idx = userIndexById.get(m.id);
        if (idx !== undefined) userOrder[idx] = m;
        userMap.set(m.id, m);
      }
    }
  }

  if (userOrder.length === 0) {
    return normalized;
  }

  // Lazy lookup table for assistant messages missing parentMessageId that link via interactionId
  let userIdByInteractionKey = null;
  const resolveParentIdByInteraction = (interactionKey) => {
    if (userIdByInteractionKey === null) {
      userIdByInteractionKey = new Map();
      for (let j = 0; j < userOrder.length; j++) {
        const u = userOrder[j];
        if (u.interactionId && !userIdByInteractionKey.has(u.interactionId)) {
          userIdByInteractionKey.set(u.interactionId, u.id);
        }
        if (u.id && !userIdByInteractionKey.has(u.id)) {
          userIdByInteractionKey.set(u.id, u.id);
        }
      }
    }
    return userIdByInteractionKey.get(interactionKey) || null;
  };

  // Step 2: Map each assistant message to its parent user message
  let runningUser = null;

  for (let i = 0; i < normalized.length; i++) {
    const m = normalized[i];
    if (!m) continue;

    if (m.sender === 'user') {
      runningUser = m;
      continue;
    }

    if (m.sender === 'assistant') {
      let parentId = m.parentMessageId;
      if (!parentId && m.interactionId) {
        parentId = resolveParentIdByInteraction(m.interactionId);
      }
      if (!parentId && runningUser) {
        parentId = runningUser.id;
      }

      if (parentId && assistantBuckets.has(parentId)) {
        const bucket = assistantBuckets.get(parentId);
        const existingIdx = bucket.findIndex((a) => a.id === m.id);
        if (existingIdx >= 0) {
          bucket[existingIdx] = m;
        } else {
          bucket.push(m);
        }
      } else {
        if (!runningUser) {
          leadingOrphans.push(m);
        } else {
          trailingOrphans.push(m);
        }
      }
    } else {
      if (!runningUser) {
        leadingOrphans.push(m);
      } else {
        trailingOrphans.push(m);
      }
    }
  }

  // Sort user prompts chronologically (stable fallback on original position)
  userOrder.sort((a, b) => {
    const timeA = typeof a.createdAtMs === 'number' ? a.createdAtMs : (a.createdAt || null);
    const timeB = typeof b.createdAtMs === 'number' ? b.createdAtMs : (b.createdAt || null);
    if (timeA !== null && timeB !== null && timeA !== timeB) {
      return timeA - timeB;
    }
    return 0;
  });

  const result = [...leadingOrphans];

  for (const userMsg of userOrder) {
    result.push(userMsg);
    const assistants = assistantBuckets.get(userMsg.id) || [];
    if (assistants.length > 1) {
      assistants.sort((a, b) => {
        const timeA = typeof a.createdAtMs === 'number' ? a.createdAtMs : (a.createdAt || 0);
        const timeB = typeof b.createdAtMs === 'number' ? b.createdAtMs : (b.createdAt || 0);
        return timeA - timeB;
      });
    }
    for (const asst of assistants) {
      result.push(asst);
    }
  }

  for (const orphan of trailingOrphans) {
    result.push(orphan);
  }

  return result;
}

/**
 * Creates an isolated, topology-aware memoized wrapper around `orderConversationMessages`.
 *
 * Avoids redundant full normalization, bucket construction, and sorting when:
 * - The exact same `messages` array reference is passed again (O(1)).
 * - A shallow copy contains identical message object references in every slot.
 * - Streaming chunks or in-place updates (e.g. active alternative switches) update message
 *   content/metadata without altering message count, IDs, sender roles, parent/interaction
 *   links, or creation timestamps.
 *
 * @param {{ onFullOrder?: () => void }} [options]
 * @returns {(messages?: Array) => Array}
 */
export function createConversationOrderMemo(options = {}) {
  const onFullOrder = typeof options?.onFullOrder === 'function' ? options.onFullOrder : null;
  /** @type {Array | null} */
  let prevInput = null;
  let prevInputLength = -1;
  /** @type {Array | null} */
  let prevOutput = null;

  return function memoizedOrderConversationMessages(messages = []) {
    if (!Array.isArray(messages)) {
      return [];
    }

    const len = messages.length;

    if (messages === prevInput && len === prevInputLength && prevOutput !== null) {
      return prevOutput;
    }

    if (messages === prevOutput && prevOutput !== null && len === prevOutput.length) {
      prevInput = prevOutput;
      prevInputLength = len;
      return prevOutput;
    }

    if (len === 0 && prevInputLength === 0 && prevOutput !== null && prevOutput.length === 0) {
      prevInput = messages;
      return prevOutput;
    }

    if (
      len > 1 &&
      prevInput !== null &&
      prevOutput !== null &&
      len === prevInputLength &&
      prevOutput.length === len
    ) {
      let canReuseTopology = true;
      let firstChangedIdx = -1;
      /** @type {Array<number> | null} */
      let extraChangedIndices = null;

      for (let i = 0; i < len; i++) {
        const prevMsg = prevInput[i];
        const nextMsg = messages[i];
        if (nextMsg === prevMsg) {
          continue;
        }
        if (!canReuseMessageSlotOrder(prevMsg, nextMsg)) {
          canReuseTopology = false;
          break;
        }
        if (firstChangedIdx === -1) {
          firstChangedIdx = i;
        } else {
          if (extraChangedIndices === null) {
            extraChangedIndices = [i];
          } else {
            extraChangedIndices.push(i);
          }
        }
      }

      if (canReuseTopology) {
        if (firstChangedIdx === -1) {
          prevInput = messages;
          prevInputLength = len;
          return prevOutput;
        }

        if (prevOutput === prevInput) {
          prevInput = messages;
          prevInputLength = len;
          prevOutput = messages;
          return messages;
        }

        const nextOutput = prevOutput.slice();
        const firstOutPos = prevOutput.indexOf(prevInput[firstChangedIdx]);
        if (firstOutPos !== -1) {
          nextOutput[firstOutPos] = messages[firstChangedIdx];
          let patchedAll = true;
          if (extraChangedIndices !== null) {
            for (let c = 0; c < extraChangedIndices.length; c++) {
              const idx = extraChangedIndices[c];
              const outPos = prevOutput.indexOf(prevInput[idx]);
              if (outPos === -1) {
                patchedAll = false;
                break;
              }
              nextOutput[outPos] = messages[idx];
            }
          }
          if (patchedAll) {
            prevInput = messages;
            prevInputLength = len;
            prevOutput = nextOutput;
            return nextOutput;
          }
        }
      }
    }

    if (onFullOrder) {
      onFullOrder();
    }
    const ordered = orderConversationMessages(messages);
    prevInput = messages;
    prevInputLength = len;
    prevOutput = ordered;
    return ordered;
  };
}


/**
 * Returns alternative navigation metrics for an assistant message.
 * @param {Object} assistantMessage
 * @returns {{ total: number, currentIndex: number, activeAlternativeId: string|null, canGoPrevious: boolean, canGoNext: boolean, alternatives: Array }}
 */
export function getAlternativeMetrics(assistantMessage) {
  if (!assistantMessage || !Array.isArray(assistantMessage.alternatives)) {
    return {
      total: 1,
      currentIndex: 0,
      activeAlternativeId: assistantMessage?.id || null,
      canGoPrevious: false,
      canGoNext: false,
      alternatives: []
    };
  }

  const alts = assistantMessage.alternatives;
  const total = Math.max(1, alts.length);
  const activeId = assistantMessage.activeAlternativeId || (alts[0]?.id ?? null);
  const currentIndex = Math.max(0, alts.findIndex((a) => a.id === activeId));

  return {
    total,
    currentIndex,
    activeAlternativeId: activeId,
    canGoPrevious: currentIndex > 0,
    canGoNext: currentIndex < total - 1,
    alternatives: alts
  };
}
